PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE jobs (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  cmd TEXT NOT NULL,
  status INTEGER NOT NULL DEFAULT 0,   -- 0=queued, 1=done, 2=running
  attempts INTEGER NOT NULL DEFAULT 0,
  rc INTEGER,
  last_start REAL,
  last_end REAL,
  stdout_path TEXT,
  stderr_path TEXT,
  host TEXT,
  pid INTEGER
);
CREATE INDEX idx_jobs_status ON jobs(status);
COMMIT;
